  'setup.mcp.projects.title': 'In a project',
  'setup.mcp.projects.description': 'Turn an MCP server on or off in one project’s checkouts, on every machine or on one. Off denies it by name in each checkout’s own .claude/settings.local.json, which Git ignores. On takes that out again and, where the machine hasn’t set the server up for every project, sets it up for the checkout alone with Claude Code’s own claude mcp add-json --scope local. The checked-in files are never changed.',
  'setup.mcp.projects.reviewDescription': 'Arbor edits each checkout’s settings.local.json, backed up first and listed on Sync › Arbor’s changes to undo. A server set up for a checkout is added by Claude Code in that checkout, as the repo defines it.',
